import { Component } from '@angular/core';
import { IonicPage, NavController, NavParams } from 'ionic-angular';

import { News } from "../../models/news";
import { NewsProvider } from "../../providers/news/news";

@IonicPage()
@Component({
  selector: 'page-news-detail',
  templateUrl: 'news-detail.html'
})
export class NewsDetailPage {
  item: any;

  defaultNews: any = {
		"titolo"          :		"titolo",
		"contenuto"       :		"contenuto",
		"posizione"       :		1,
		"abilitato"       :		1,
		"in_evidenza"     :		0,
		"img"             :		"assets/img/speakers/bear.jpg",
		"data_news"       :		1514678011,
		"data_scadenza"   :		null,
		"last_update"     :		1514678011,
		"cancellato"      :		0
  	};

  constructor(public navCtrl: NavController, navParams: NavParams, items: NewsProvider) {
    this.item = navParams.get('item') || this.defaultNews;
  }

}



